from kodi_six import xbmc


class InfoTagHelper(object):
    """Kodi 20+ InfoTagVideo helpers.

    Value conversion follows ListItem.setInfo("video"): the same checks that
    used to live next to the Kodi 20 call sites in navigation.py.
    """

    # ListItem fields that setInfo() still sets without the deprecation warning
    LISTITEM_INFO_KEYS = ("count", "size", "overlay", "date")

    @staticmethod
    def _int(value):
        try:
            return int(value)
        except (TypeError, ValueError):
            try:
                return int(float(value))
            except (TypeError, ValueError):
                return 0

    @staticmethod
    def _float(value):
        try:
            return float(value)
        except (TypeError, ValueError):
            return 0.0

    @staticmethod
    def _votes(value):
        # setInfo() kept only the digits, e.g. "12,345"
        return int("".join(c for c in str(value) if c.isdigit()) or 0)

    @staticmethod
    def _str(value):
        return value if isinstance(value, str) else str(value)

    @staticmethod
    def _list(value):
        if isinstance(value, (list, tuple)):
            return [InfoTagHelper._str(v) for v in value]
        # shortcut: Kodi splits strings by advancedsettings' videoitemseparator, assume the default
        return InfoTagHelper._str(value).split(" / ") if value else []

    @classmethod
    def _video_info_setters(cls):
        # setInfo("video") keys and their InfoTagVideo setters, converting values the way setInfo() did
        return {
            "dbid": ("setDbId", cls._int),
            "year": ("setYear", cls._int),
            "episode": ("setEpisode", cls._int),
            "season": ("setSeason", cls._int),
            "sortepisode": ("setSortEpisode", cls._int),
            "sortseason": ("setSortSeason", cls._int),
            "episodeguide": ("setEpisodeGuide", cls._str),
            "showlink": ("setShowLinks", cls._list),
            "top250": ("setTop250", cls._int),
            "setid": ("setSetId", cls._int),
            "tracknumber": ("setTrackNumber", cls._int),
            "userrating": ("setUserRating", cls._int),
            "watched": ("setPlaycount", cls._int),
            "playcount": ("setPlaycount", cls._int),
            "artist": ("setArtists", cls._list),
            "genre": ("setGenres", cls._list),
            "country": ("setCountries", cls._list),
            "director": ("setDirectors", cls._list),
            "mpaa": ("setMpaa", cls._str),
            "plot": ("setPlot", cls._str),
            "plotoutline": ("setPlotOutline", cls._str),
            "title": ("setTitle", cls._str),
            "originaltitle": ("setOriginalTitle", cls._str),
            "sorttitle": ("setSortTitle", cls._str),
            "duration": ("setDuration", cls._int),
            "studio": ("setStudios", cls._list),
            "tagline": ("setTagLine", cls._str),
            "writer": ("setWriters", cls._list),
            "credits": ("setWriters", cls._list),
            "tvshowtitle": ("setTvShowTitle", cls._str),
            "premiered": ("setPremiered", cls._str),
            "status": ("setTvShowStatus", cls._str),
            "set": ("setSet", cls._str),
            "setoverview": ("setSetOverview", cls._str),
            "tag": ("setTags", cls._list),
            "imdbnumber": ("setIMDBNumber", cls._str),
            "code": ("setProductionCode", cls._str),
            "aired": ("setFirstAired", cls._str),
            "lastplayed": ("setLastPlayed", cls._str),
            "album": ("setAlbum", cls._str),
            "votes": ("setVotes", cls._votes),
            "trailer": ("setTrailer", cls._str),
            "path": ("setPath", cls._str),
            "filenameandpath": ("setFilenameAndPath", cls._str),
            "dateadded": ("setDateAdded", cls._str),
            "mediatype": ("setMediaType", cls._str),
        }

    @classmethod
    def apply_video(cls, list_item, info_tag, labels):
        """Kodi 20+ replacement for setInfo("video"), which logs a deprecation warning on every call."""
        rest = {}
        setters = cls._video_info_setters()
        for key, value in labels.items():
            key = key.lower()
            if key in cls.LISTITEM_INFO_KEYS:
                rest[key] = value
            elif key == "rating":
                # setRating() resets votes, so pass them together
                info_tag.setRating(cls._float(value), cls._votes(labels.get("votes", 0)))
            elif key == "votes" and "rating" in labels:
                continue
            elif key in setters:
                setter, convert = setters[key]
                getattr(info_tag, setter)(convert(value))
        if rest:
            list_item.setInfo("video", rest)

    @staticmethod
    def apply_cast(info_tag, castmembers):
        actors = []
        for castmember in castmembers:
            # infolabels JSON parses numbers as strings; Actor.order must be an int
            if 'order' in castmember:
                castmember['order'] = int(castmember['order'])
            actor = xbmc.Actor(name=castmember.get('name', ''),
                               role=castmember.get('role', ''),
                               thumbnail=castmember.get('thumbnail', ''),
                               order=castmember.get('order', -1))
            actors.append(actor)
        info_tag.setCast(actors)

    @staticmethod
    def apply_stream_info(info_tag, stream_info):
        for type_, values in stream_info.items():
            if type_ == "video":
                video_stream_detail = xbmc.VideoStreamDetail(
                    width=values.get('width', 0),
                    height=values.get('height', 0),
                    aspect=values.get('aspect', 0),
                    duration=values.get('duration', 0),
                    codec=values.get('codec', ''),
                    language=values.get('language', ''),
                )
                info_tag.addVideoStream(video_stream_detail)
            elif type_ == "audio":
                audio_stream_detail = xbmc.AudioStreamDetail(
                    language=values.get('language', ''),
                    codec=values.get('codec', ''),
                    channels=values.get('channels', -1),
                )
                info_tag.addAudioStream(audio_stream_detail)
            elif type_ == "subtitle":
                subtitle_stream_detail = xbmc.SubtitleStreamDetail(
                    language=values.get('language', ''),
                )
                info_tag.addSubtitleStream(subtitle_stream_detail)

    @staticmethod
    def apply_resume_point(info_tag, properties):
        if "resumetime" in properties and "totaltime" in properties:
            info_tag.setResumePoint(
                float(properties["resumetime"]),
                float(properties["totaltime"]),
            )
            del properties["resumetime"]
            del properties["totaltime"]
